// Las variables de entorno son siempre texto. Esta función las convierte y las valida.
// Recibe un objeto (en Node le pasarías process.env) para que se pueda probar acá.
function leerConfig(env) {
  const errores = [];
  const texto = (nombre, porDefecto) => {
    const v = env[nombre];
    if (v !== undefined && v !== '') return v;
    if (porDefecto === undefined) errores.push(`falta ${nombre}`);
    return porDefecto;
  };
  const entero = (nombre, porDefecto) => {
    const v = texto(nombre, porDefecto);
    const n = Number(v);
    if (v !== undefined && !Number.isInteger(n)) errores.push(`${nombre} tiene que ser un entero y llegó «${v}»`);
    return n;
  };
  const booleano = (nombre, porDefecto) => {
    const v = texto(nombre, porDefecto);
    if (v !== 'true' && v !== 'false') errores.push(`${nombre} tiene que ser true o false y llegó «${v}»`);
    return v === 'true';
  };
  const config = {
    apiUrl: texto('API_URL'),
    puerto: entero('PORT', '3000'),
    depurar: booleano('DEBUG', 'false'),
  };
  if (errores.length > 0) throw new Error('Configuración inválida:\n - ' + errores.join('\n - '));
  return config;
}

// 1) El error clásico: el texto "false" es verdadero
const crudo = { DEBUG: 'false' };
console.log('if (env.DEBUG) con "false" ->', crudo.DEBUG ? 'entra (¡activó la depuración!)' : 'no entra');

// 2) Con valores razonables
console.log(leerConfig({ API_URL: 'https://api.ejemplo.test', PORT: '8080' }));

// 3) Con valores rotos: falla al arrancar y dice todo lo que está mal
try {
  leerConfig({ PORT: 'ocho mil', DEBUG: 'si' });
} catch (e) {
  console.log(e.message);
}
